// Presión y saturación derivadas del estado
const evolveVitals=(base,kind)=>{
  const sys=parseInt(String(base.bp))||120;
  const dia=parseInt(String(base.bp).split('/')[1])||70;
  if(kind==='ok')  return {bp:`${Math.min(135,Math.max(105,sys+18))}/${Math.min(85,dia+8)}`, spo2:Math.min(99,(base.spo2||96)+3)};
  if(kind==='bad') return {bp:`${Math.max(62,sys-32)}/${Math.max(38,dia-20)}`,             spo2:Math.max(84,(base.spo2||96)-8)};
  return {bp:'0/0', spo2:0};
};

// Examen físico redactado a partir de los signos vitales
const examFromVitals=(v,lang)=>{
  const hr=v.hr||0, sys=parseInt(String(v.bp))||0, spo2=v.spo2||0;
  const P={
    es:{ hi:'Taquicárdico, pulso rápido y de amplitud disminuida.', lo:'Bradicárdico, pulso lento y amplio.', mid:'Pulso regular de amplitud conservada.',
         hypo:'Piel fría y pálida, relleno capilar prolongado, signos de hipoperfusión.', norm:'Piel tibia y bien perfundida, relleno capilar menor a 2 segundos.',
         desat:'Taquipneico, con saturación por debajo del objetivo pese al oxígeno suplementario.', ok:'Eupneico, sin trabajo respiratorio.',
         arrest:'Sin pulso central palpable. Apnea. No responde a estímulos.' },
    en:{ hi:'Tachycardic, rapid pulse of reduced amplitude.', lo:'Bradycardic, slow full pulse.', mid:'Regular pulse of preserved amplitude.',
         hypo:'Cold pale skin, prolonged capillary refill, signs of hypoperfusion.', norm:'Warm well-perfused skin, capillary refill under 2 seconds.',
         desat:'Tachypneic, saturation below target despite supplemental oxygen.', ok:'Eupneic, no respiratory distress.',
         arrest:'No palpable central pulse. Apnea. Unresponsive.' },
    pt:{ hi:'Taquicárdico, pulso rápido e de amplitude diminuída.', lo:'Bradicárdico, pulso lento e amplo.', mid:'Pulso regular de amplitude preservada.',
         hypo:'Pele fria e pálida, enchimento capilar prolongado, sinais de hipoperfusão.', norm:'Pele quente e bem perfundida, enchimento capilar menor que 2 segundos.',
         desat:'Taquipneico, saturação abaixo do alvo apesar do oxigênio suplementar.', ok:'Eupneico, sem esforço respiratório.',
         arrest:'Sem pulso central palpável. Apneia. Não responde a estímulos.' },
  }[lang];
  if(hr===0||sys===0) return P.arrest;
  const parts=[hr>110?P.hi:hr<55?P.lo:P.mid, sys<90?P.hypo:P.norm, spo2<92?P.desat:P.ok];
  return parts.join(' ');
};

