const followupFor=(rhythm)=>{
  if(rhythm==='afib'||rhythm==='flutter'||rhythm==='pac') return FOLLOWUP.afib;
  if(rhythm==='vt'||rhythm==='pvc'||rhythm==='aivr'||rhythm==='idiovent') return FOLLOWUP.vent;
  if(rhythm==='avblock1'||rhythm==='avblock2'||rhythm==='avblock3'||rhythm==='mobitz1'||rhythm==='mobitz2'||rhythm==='sinusbrady'||rhythm==='nodal') return FOLLOWUP.block;
  if(rhythm==='svt'||rhythm==='wpw') return FOLLOWUP.supra;
  if(rhythm==='vf'||rhythm==='asystole') return FOLLOWUP.arrest;
  return FOLLOWUP.general;
};

// Lecciones del desenlace, construidas con el feedback real del caso
const outcomeLessons=(c,lang)=>{
  const ok=c.options.find(o=>o.correct);
  const wrongs=c.options.filter(o=>!o.correct);
  const L={es:['Conducta correcta: ','Errores frecuentes en este escenario:'],
           en:['Correct management: ','Common errors in this scenario:'],
           pt:['Conduta correta: ','Erros frequentes neste cenário:']}[lang];
  return [L[0]+ok.text[lang]+' — '+ok.feedback[lang], L[1],
          ...wrongs.map(w=>'· '+w.text[lang]+': '+w.feedback[lang])];
};

// ── Construcción del escenario ramificado ──
function buildSimCase(c,idx){
  // Caso escrito a medida: se usa tal cual, tomando paciente y nombre del ritmo del caso original
  const B=BESPOKE_SIM[c.id];
  if(B) return {
    id:'sim_'+c.id, fromCase:c.id,
    tier:B.tier||2, icon:B.icon||'🩺',
    tag:{es:T.es.rhythms[c.rhythm],en:T.en.rhythms[c.rhythm],pt:T.pt.rhythms[c.rhythm]},
    patient:c.patient,
    scene:B.scene, history:B.history||c.history, exam:B.exam,
    start:B.start, nodes:B.nodes, bespoke:true,
  };
  const ev=RHYTHM_EVOLUTION[c.rhythm]||{ok:{r:'normal',hr:80},bad:{r:c.rhythm,hr:(c.vitals.hr||80)+30},crit:{r:c.rhythm,hr:(c.vitals.hr||80)+50}};
  const vOk={hr:ev.ok.hr,...evolveVitals(c.vitals,'ok'),rr:16};
  const vBad={hr:ev.bad.hr,...evolveVitals(c.vitals,'bad'),rr:26};
  const vCrit=ev.crit.hr===0?{hr:0,bp:'0/0',spo2:0,rr:0}:{hr:ev.crit.hr,...evolveVitals(c.vitals,'bad'),rr:30};
  const correct=c.options.find(o=>o.correct);
  const wrongs=c.options.filter(o=>!o.correct);
  const tri=(fn)=>({es:fn('es'),en:fn('en'),pt:fn('pt')});
  const pick=(o,q,pts,next,tag)=>({
    id:tag,q,pts,next,
    text:o.text,
    fb:{es:(q==='correct'?'✅ ':q==='partial'?'⚠️ ':'❌ ')+o.feedback.es,
        en:(q==='correct'?'✅ ':q==='partial'?'⚠️ ':'❌ ')+o.feedback.en,
        pt:(q==='correct'?'✅ ':q==='partial'?'⚠️ ':'❌ ')+o.feedback.pt},
  });
  const fu=followupFor(c.rhythm);
  const shuffleStable=(arr)=>arr;

  return {
    id:'sim_'+c.id, tier:(RHYTHM_DIFF&&RHYTHM_DIFF[c.rhythm])||2, icon:'🩺', fromCase:c.id,
    tag:tri(l=>T[l].rhythms[c.rhythm]),
    patient:c.patient,
    scene:tri(l=>SIM_TXT.scene[l](c.patient[l])),
    history:c.history,
    exam:tri(l=>examFromVitals(c.vitals,l)),
    start:'a1',
    nodes:{
      // ── Presentación ──
      a1:{ rhythm:c.rhythm, vitals:{...c.vitals,rr:c.vitals.hr>110?24:c.vitals.hr<50?12:16},
        narrative:tri(l=>SIM_TXT.arrive[l]),
        question:tri(l=>SIM_TXT.q1[l]),
        choices:[
          pick(correct,'correct',40,'a_ok','c_ok'),
          ...wrongs.map((w,i)=>pick(w,'wrong',-15,'a_bad','c_w'+i)),
        ]},

      // ── Deterioro: segunda oportunidad con las opciones restantes ──
      a_bad:{ rhythm:ev.bad.r, vitals:vBad,
        narrative:tri(l=>SIM_TXT.worse[l]),
        question:tri(l=>SIM_TXT.q2[l]),
        choices:[
          pick(correct,'correct',25,'a_ok2','r_ok'),
          ...wrongs.slice(0,2).map((w,i)=>pick(w,'wrong',-20,'a_crit','r_w'+i)),
        ]},

      // ── Estado crítico: última oportunidad ──
      a_crit:{ rhythm:ev.crit.r, vitals:vCrit,
        narrative:tri(l=>SIM_TXT.crit[l]),
        question:tri(l=>SIM_TXT.q3[l]),
        choices:[
          pick(correct,'correct',15,'end_rescue','k_ok'),
          pick(wrongs[wrongs.length-1],'fatal',-30,'end_death','k_w'),
        ]},

      // ── Mejoría tras acertar de entrada ──
      a_ok:{ rhythm:ev.ok.r, vitals:vOk,
        narrative:tri(l=>SIM_TXT.improved[l]),
        question:tri(l=>SIM_TXT.qFollow[l]),
        choices:fu.map((f,i)=>({id:'f'+i,q:f.ok?'correct':(f.pts>0?'partial':'wrong'),pts:f.pts,
          next:f.ok?'end_success':'end_partial',text:f.t,fb:f.f})),
      },

      // ── Mejoría tras rectificar ──
      a_ok2:{ rhythm:ev.ok.r, vitals:vOk,
        narrative:tri(l=>SIM_TXT.improved[l]),
        question:tri(l=>SIM_TXT.qFollow[l]),
        choices:fu.map((f,i)=>({id:'g'+i,q:f.ok?'correct':(f.pts>0?'partial':'wrong'),pts:f.pts,
          next:f.ok?'end_rescue':'end_partial',text:f.t,fb:f.f})),
      },

      // ── Desenlaces ──
      end_success:{ terminal:'success', rhythm:ev.ok.r, vitals:vOk,
        title:{es:'Manejo correcto',en:'Correct management',pt:'Manejo correto'},
        narrative:tri(l=>({
          es:'El paciente queda estable y con el ritmo controlado. Se completa el estudio de la causa y se define la conducta de fondo antes del alta o del pase a sala.',
          en:'The patient remains stable with the rhythm controlled. The cause is worked up and definitive management is defined before discharge or ward transfer.',
          pt:'O paciente permanece estável e com o ritmo controlado. Completa-se a investigação da causa e define-se a conduta de fundo antes da alta.'}[l])),
        lessons:tri(l=>outcomeLessons(c,l))},

      end_rescue:{ terminal:'rescue', rhythm:ev.ok.r, vitals:vOk,
        title:{es:'Rescatado tras rectificar',en:'Rescued after correcting course',pt:'Resgatado após corrigir'},
        narrative:tri(l=>({
          es:'La conducta correcta llega tarde pero llega: el paciente se recupera. El deterioro intermedio era evitable y prolongó la internación.',
          en:'The correct management arrives late but it arrives: the patient recovers. The intervening deterioration was avoidable and prolonged the admission.',
          pt:'A conduta correta chega tarde, mas chega: o paciente se recupera. A deterioração intermediária era evitável e prolongou a internação.'}[l])),
        lessons:tri(l=>outcomeLessons(c,l))},

      end_partial:{ terminal:'partial', rhythm:ev.ok.r, vitals:vOk,
        title:{es:'Estabilizado, manejo incompleto',en:'Stabilized, incomplete management',pt:'Estabilizado, manejo incompleto'},
        narrative:tri(l=>({
          es:'El ritmo se controló, pero el manejo de fondo quedó sin resolver. El paciente vuelve a consultar por el mismo motivo semanas después.',
          en:'The rhythm was controlled, but definitive management was left unresolved. The patient returns with the same problem weeks later.',
          pt:'O ritmo foi controlado, mas o manejo de fundo ficou por resolver. O paciente retorna pelo mesmo motivo semanas depois.'}[l])),
        lessons:tri(l=>outcomeLessons(c,l))},

      end_death:{ terminal:'death', rhythm:ev.crit.hr===0?'asystole':ev.crit.r, vitals:{hr:0,bp:'0/0',spo2:0,rr:0},
        title:{es:'Desenlace fatal',en:'Fatal outcome',pt:'Desfecho fatal'},
        narrative:tri(l=>({
          es:'La acumulación de conductas equivocadas agotó el margen del paciente. Se inicia reanimación sin respuesta. El escenario tenía una conducta correcta disponible desde el primer momento.',
          en:'The accumulation of wrong decisions exhausted the patient reserve. Resuscitation is started without response. The scenario had a correct management available from the very first moment.',
          pt:'O acúmulo de condutas equivocadas esgotou a margem do paciente. Inicia-se reanimação sem resposta. O cenário tinha uma conduta correta disponível desde o primeiro momento.'}[l])),
        lessons:tri(l=>outcomeLessons(c,l))},
    }
  };
}

const SIM_CASES=CASES.map((c,i)=>buildSimCase(c,i));
const ALL_SIM_CASES=[...BRANCH_CASES,...SIM_CASES];

// ═══════════════════════════════════════════════════════════════
// BITÁCORA DE ERRORES
// Guarda referencias (no texto) para poder releer el fundamento
// exacto de cada equivocación. Alimentada por quiz, casos y simulador.
// ═══════════════════════════════════════════════════════════════
const ERR_KEY='sistole_mistakes_v1';
const ERR_MAX=60;
const loadErrs=()=>{try{const s=localStorage.getItem(nk(ERR_KEY));if(s)return JSON.parse(s);}catch(e){}return[];};
const saveErrs=(d)=>{try{localStorage.setItem(nk(ERR_KEY),JSON.stringify(d));}catch(e){}};

function useMistakes(accountKey){
  const [mistakes,setMistakes]=useState(loadErrs);
  useEffect(()=>{setMistakes(loadErrs());},[accountKey]);

  // Un error se agrupa por su firma: mismo origen, mismo ritmo, misma opción elegida
  const logMistake=useCallback((m)=>{
    if(!m||!m.rhythm) return;
    setMistakes(prev=>{
      const sig=[m.src,m.rhythm,m.caseId||'',m.node||'',m.choiceId||'',m.chose||''].join('|');
      const i=prev.findIndex(x=>x.sig===sig);
      let next;
      if(i>=0){
        next=[...prev];
        next[i]={...next[i],n:(next[i].n||1)+1,at:Date.now()};
      } else {
        next=[{...m,sig,n:1,at:Date.now()},...prev];
      }
      next.sort((a,b)=>b.at-a.at);
      next=next.slice(0,ERR_MAX);
      saveErrs(next);
      return next;
    });
  },[]);

  const resolveMistake=useCallback((sig)=>{
    setMistakes(prev=>{const next=prev.filter(x=>x.sig!==sig);saveErrs(next);return next;});
  },[]);

  const clearMistakes=useCallback(()=>{setMistakes([]);saveErrs([]);},[]);

  // Ritmos con errores pendientes, del más fallado al menos
  const weakRhythms=useMemo(()=>{
    const tally={};
    mistakes.forEach(m=>{tally[m.rhythm]=(tally[m.rhythm]||0)+(m.n||1);});
    return Object.entries(tally).sort((a,b)=>b[1]-a[1]).map(([r,n])=>({rhythm:r,n}));
  },[mistakes]);

  return{mistakes,logMistake,resolveMistake,clearMistakes,weakRhythms};
}

// ── Recupera el texto original del error, sin haberlo duplicado en memoria ──
function mistakeDetail(m,lang){
  const R=(k)=>(T[lang]&&T[lang].rhythms&&T[lang].rhythms[k])||k;
  if(m.src==='quiz'){
    return {
      title:{es:`Confundiste ${R(m.rhythm)} con ${R(m.chose)}`,
             en:`You mistook ${R(m.rhythm)} for ${R(m.chose)}`,
             pt:`Confundiu ${R(m.rhythm)} com ${R(m.chose)}`}[lang],
      body:(T[lang]&&T[lang].desc&&T[lang].desc[m.rhythm])||'',
      tag:{es:'Reconocimiento',en:'Recognition',pt:'Reconhecimento'}[lang],
    };
  }
  if(m.src==='case'){
    const c=CASES.find(x=>x.id===m.caseId);
    const o=c&&c.options[m.chose];
    return {
      title:o?o.text[lang]:R(m.rhythm),
      body:o?o.feedback[lang]:'',
      tag:{es:'Caso clínico',en:'Clinical case',pt:'Caso clínico'}[lang],
      patient:c?c.patient[lang]:null,
    };
  }
  // simulador ramificado
  const c=ALL_SIM_CASES.find(x=>x.id===m.caseId);
  const nd=c&&c.nodes[m.node];
  const ch=nd&&nd.choices&&nd.choices.find(x=>x.id===m.choiceId);
  return {
    title:ch?ch.text[lang]:R(m.rhythm),
    body:ch?ch.fb[lang]:'',
    tag:{es:'Simulador',en:'Simulator',pt:'Simulador'}[lang],
    patient:c?c.patient[lang]:null,
  };
}

function MistakeReview({mistakes,lang,onResolve,onClear,onDrill}){
  const [open,setOpen]=useState(false);
  const [expanded,setExpanded]=useState(null);
  const L={
    title:{es:'Repaso de errores',en:'Mistake review',pt:'Revisão de erros'},
    empty:{es:'Todavía no registraste errores. Cuando falles una pregunta o tomes una decisión equivocada en un caso, va a quedar acá con su fundamento para que puedas releerlo.',
           en:'No mistakes recorded yet. When you miss a question or make a wrong decision in a case, it will appear here with its rationale so you can read it again.',
           pt:'Ainda não registrou erros. Quando errar uma pergunta ou tomar uma decisão equivocada, ficará aqui com o fundamento.'},
    drill:{es:'Practicar estos ritmos',en:'Drill these rhythms',pt:'Praticar estes ritmos'},
    got:{es:'Ya lo entendí',en:'Got it',pt:'Entendi'},
    clear:{es:'Vaciar la bitácora',en:'Clear the log',pt:'Esvaziar o registro'},
    times:{es:'veces',en:'times',pt:'vezes'},
  };
  const srcColor={quiz:'text-sky-400 border-sky-800/40 bg-sky-950/20',
                  case:'text-emerald-400 border-emerald-800/40 bg-emerald-950/20',
                  sim:'text-violet-400 border-violet-800/40 bg-violet-950/20'};
  return(
    <div>
      <button onClick={()=>setOpen(v=>!v)} className="w-full flex items-center justify-between py-1 group">
        <div className="font-mono text-[11px] text-stone-500 uppercase tracking-widest">
          {L.title[lang]}
          {mistakes.length>0&&<span className="ml-2 text-rose-400">({mistakes.length})</span>}
        </div>
        <span className={`text-stone-600 text-xs transition-transform ${open?'rotate-90':''}`}>▶</span>
      </button>

      {open&&(
        <div className="mt-3 space-y-2">
          {mistakes.length===0?(
            <div className="px-4 py-4 rounded-xl bg-stone-900/40 border border-stone-800/80">
              <p className="text-stone-500 text-[13px] leading-relaxed">{L.empty[lang]}</p>
            </div>
          ):(
            <>
              <button onClick={onDrill}
                className="w-full py-2.5 rounded-xl bg-sky-900/40 border border-sky-800/50 text-sky-200 hover:bg-sky-800/50 text-sm font-medium transition-colors">
                🎯 {L.drill[lang]}
              </button>

              {mistakes.map(m=>{
                const d=mistakeDetail(m,lang);
                const isOpen=expanded===m.sig;
                return(
                  <div key={m.sig} className={`rounded-xl border overflow-hidden ${srcColor[m.src]||srcColor.quiz}`}>
                    <button onClick={()=>setExpanded(isOpen?null:m.sig)}
                      className="w-full text-left px-3.5 py-3 hover:bg-black/20 transition-colors">
                      <div className="flex items-start gap-2.5">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1 flex-wrap">
                            <span className={`font-mono text-[9px] uppercase tracking-wider ${srcColor[m.src]?.split(' ')[0]||''}`}>{d.tag}</span>
                            <span className="font-mono text-[9px] text-stone-600">
                              {(T[lang]&&T[lang].rhythms&&T[lang].rhythms[m.rhythm])||m.rhythm}
                            </span>
                            {m.n>1&&<span className="font-mono text-[9px] text-rose-400">×{m.n} {L.times[lang]}</span>}
                          </div>
                          <div className="text-stone-200 text-[13px] leading-snug">{d.title}</div>
                          {d.patient&&<div className="text-stone-600 text-[11px] mt-0.5">{d.patient}</div>}
                        </div>
                        <span className={`text-stone-600 text-xs flex-shrink-0 mt-0.5 transition-transform ${isOpen?'rotate-90':''}`}>▶</span>
                      </div>
                    </button>
                    {isOpen&&(
                      <div className="px-3.5 pb-3.5 pt-0.5 border-t border-white/5">
                        <p className="text-stone-300 text-[13px] leading-relaxed mb-3">{d.body}</p>
                        <button onClick={()=>onResolve(m.sig)}
                          className="px-3 py-1.5 rounded-lg bg-stone-800 hover:bg-stone-700 text-stone-300 text-xs transition-colors">
                          ✓ {L.got[lang]}
                        </button>
                      </div>
                    )}
                  </div>
                );
              })}

              <button onClick={onClear}
                className="w-full py-2 text-[11px] font-mono text-stone-600 hover:text-rose-400 transition-colors">
                {L.clear[lang]}
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
}



